<?php
 namespace ehr; interface iPractitionerResourceItem extends iResourceItemMan { } class PractitionerResourceItem extends ResourceItemMan implements iPractitionerResourceItem { private const LINK_ATTR_PRACTITIONER = 'Practitioner'; public function __construct(Resource $aResource) { parent::__construct($aResource); } public function initData(array $record): void { parent::initData($record); $this->state = $record['state'] ?? 0; if (!empty($this->pin) && !empty($this->errorPersonalNumber)) { $this->getResource()->getLink()->getLogger()->addLog( "; врач {$this->getFIO()}, key: {$this->getId()}", '', Logger::LMT_WARN, true ); $this->pin = ''; } } public function initJSONbase(): void { parent::initJSONbase(); LinkJSON::addNode($this->json, 'resourceType', self::LINK_ATTR_PRACTITIONER); if (!empty($this->pin)) { LinkJSON::addIdentifierV($this->json, LinkSetup::ID_URL_DRPIN, $this->pin); } $this->addFIONode($this->json); $role = &LinkJSON::addNode($this->json, 'PractitionerRole'); $ma = &LinkJSON::addNode($role, 'managingOrganization'); LinkJSON::addNodeEx($ma, 'reference', "Organization/{$this->getResource()->getLs()->getParam('enterpriseFHIR')}"); LinkJSON::addCodeableConceptC($role, 'role', LinkSetup::ID_URL_PROLE, 'doctor'); } public function appendJSON(): void { parent::appendJSON(); if (!empty($this->guid)) { LinkJSON::addNodeEx($this->json, 'id', $this->guid); } if (!empty($this->versionGUID)) { $meta = &LinkJSON::addNode($this->json, 'meta'); LinkJSON::addNodeEx($meta, 'versionId', $this->versionGUID); } } public function getProfileSDvalue(): string { return LinkSetup::ID_URL_SD_PRACTICIONER; } private function addReferenceDoctor(\stdClass &$node, string $name): void { if (empty($this->getGUID())) { throw new Exception($this->makeReferenceErrorMessage(self::MSG_ERROR_DOCTOR)); } $this->addSubReference($node, $name, self::LINK_ATTR_PRACTITIONER); } } 